<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\MagicLink\Infrastructure\Driven;

use Override;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationRequest;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\ChallengesState;
use Civi\Lughauth\Features\OAuth\Client\Domain\Gateway\ClientStoreGateway;
use Civi\Lughauth\Features\OAuth\Session\Domain\Gateway\TemporalKeysGateway;
use Civi\Lughauth\Features\OAuth\Session\Domain\TemporalAuthCode;
use Civi\Lughauth\Features\OAuth\User\Domain\Gateway\LoginGateway;
use Civi\Lughauth\Features\OAuth\MagicLink\Domain\Gateway\MagicLinkCodeGateway;

/**
 * Infrastructure adapter that bridges the MagicLinkCodeGateway port to the authentication
 * and session subsystems.
 *
 * Resolves the OAuth client, constructs a synthetic AuthenticationRequest for the magic-link
 * flow, loads the user's pre-authenticated state via LoginGateway, and registers a short-lived
 * TemporalAuthCode through TemporalKeysGateway. The returned code is an opaque UUID stored in
 * the _oauth_temporal_codes table with a 3-minute TTL. This adapter is the single point where
 * the magic-link feature plugs into the standard authorization code machinery.
 */
class MagicLinkCodeAdapter implements MagicLinkCodeGateway
{
    public function __construct(
        private readonly LoginGateway $loginGateway,
        private readonly ClientStoreGateway $clientStore,
        private readonly TemporalKeysGateway $temporalKeys,
    ) {
    }

    /**
     * Constructs and stores a temporary authorization code for the specified user and client.
     * Throws \DomainException if the client identifier cannot be resolved to an active client record.
     */
    #[Override]
    public function createAuthCode(
        string $userUid,
        string $clientId,
        string $scope,
        string $redirectUri,
        string $tenant,
        string $nonce = '',
    ): string {
        $client = $this->clientStore->preValidatedClient($clientId);
        if ($client === null) {
            throw new \DomainException('Client not found: ' . $clientId);
        }

        $authRequest = new AuthenticationRequest(
            client: $client,
            scope: $scope,
            redirect: $redirectUri,
            responseType: 'code',
            audiences: [$clientId],
        );

        $challenges = (new ChallengesState())->withUsername($userUid);
        $authResult = $this->loginGateway->fillPreLoadById($tenant, $authRequest, $challenges);

        $temporalCode = new TemporalAuthCode(
            data: $authResult,
            client: $client,
            nonce: $nonce,
            request: $authRequest,
        );

        return $this->temporalKeys->registerTemporalAuthCode($temporalCode);
    }
}
